require("config.defaults")

-- Autostart wiki https://wiki.hyprland.org/Configuring/Keywords/#executing

local HOME = "/home/lare"

local scriptsDir = HOME .. "/.config/hypr/scripts"
local hyprDir = HOME .. "/.config/hypr"

local idlehandler = "swayidle -w timeout 300 'swaylock -f -c 000000' timeout 300 '' resume '' before-sleep 'swaylock -f -c 000000'"

-- ## Slow app launch fix

-- ## Idle configuration

-- Startup

hl.on("hyprland.start", function()
    hl.exec_cmd("waybar &")
    hl.exec_cmd("fcitx5 -d &")
    hl.exec_cmd("mako &")
    hl.exec_cmd("nm-applet --indicator &")
    hl.exec_cmd("bash -c \"mkfifo /tmp/$HYPRLAND_INSTANCE_SIGNATURE.wob && tail -f /tmp/$HYPRLAND_INSTANCE_SIGNATURE.wob | wob & disown\" &")
    hl.exec_cmd("/usr/lib/polkit-kde-authentication-agent-1 &")
    hl.exec_cmd("systemctl --user import-environment &")
    hl.exec_cmd("hash dbus-update-activation-environment 2>/dev/null &")
    hl.exec_cmd("dbus-update-activation-environment --systemd &")
    hl.exec_cmd(idlehandler)
    hl.exec_cmd(scriptsDir .. "/startup")
    hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("systemctl --user import-environment WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("hyprctl setcursor catppuccin-mocha-mauve-cursors 24")
    hl.exec_cmd(scriptsDir .. "/portal")
end)

